param([Parameter(Mandatory=$true)][string]$OutputPath)
$ErrorActionPreference='Stop';$rules=@();$form='1603q-v2018';$rev='2018-01-01'
function Add-R($id,$phase,$order,$condition,$fields,$message,$ref,$assessment='verified-correct',$behavior='Stops or mutates as described.',$recommend='Apply the rule explicitly and deterministically.',$confidence='high',$questions=@()){$script:rules += [ordered]@{rule_id=$id;form_id=$form;revision=$rev;phase=$phase;order=$order;condition=$condition;fields=@($fields);accepted_behavior='Condition is false and processing continues.';rejected_behavior=$behavior;exact_message=$message;source_refs=@($ref);evidence_type=@('source');assessment=$assessment;official_behavior=$behavior;recommended_app_behavior=$recommend;confidence=$confidence;unresolved_questions=@($questions)}}
Add-R '1603q-input-001' 'input' $null 'A money field loses focus with blank, malformed, or negative text.' @('money-fields') $null 'official-hta-runtime#blockletter:L2796-L2804' 'official-bug-compatible' 'parseFloat/toFixed silently replaces NaN with 0.00 and accepts negative values.' 'Reject malformed or disallowed negative values and use decimals.'
Add-R '1603q-input-002' 'input' $null 'A whole-number field loses focus with malformed text.' @('whole-number-fields') $null 'official-hta-runtime#blockletterWithout2Decimal:L2806-L2815' 'official-bug-compatible' 'Malformed input is silently cleared; numeric input is rounded to an integer.' 'Validate complete values explicitly.'
Add-R '1603q-change-001' 'blur/change' $null 'validateYear runs for any normal four-digit current year.' @('frm1603Q:txtYear') 'Invalid year. Year should not be later than the current year.' 'official-hta-runtime#validateYear:L2817-L2828' 'incorrect-official-behavior' 'Uses Date.getYear() (years since 1900), so a four-digit year exceeds it and is reset to values such as 126.' 'Compare with getFullYear and never replace with a two/three-digit offset.'
Add-R '1603q-change-002' 'blur/change' $null 'validateYear receives a year earlier than 2018.' @('frm1603Q:txtYear') 'Please file using the old version of the form.' 'official-hta-runtime#validateYear:L2817-L2824' 'incorrect-official-behavior' 'First resets to 2018, then the getYear defect immediately treats 2018 as future and resets again.' 'Stop after a single revision-bound error.'
Add-R '1603q-change-003' 'blur/change' $null 'Item 4 changes and the user confirms.' @('frm1603Q:TaxWithheld_1','frm1603Q:TaxWithheld_2') "Changing Item #4 will clear all computed data.`nDo you want to continue?" 'official-hta-runtime#changeTaxWitheld:L3107-L3124' 'verified-correct' 'Clears all computed data; No disables Schedule 1 and Yes enables it.' 'Use a reversible confirmation.'
Add-R '1603q-change-004' 'blur/change' $null 'Return year changes and user confirms.' @('frm1603Q:txtYear') "Changing the return period will clear all computed data.`nDo you want to continue?" 'official-hta-runtime#clearYearData:L3206-L3214' 'official-bug-compatible' 'Confirmation clears computation but cancellation writes the passed yearValue back, whose caller semantics require UI testing.'
Add-R '1603q-change-005' 'blur/change' $null 'Special Tax No is selected.' @('frm1603Q:SpecialTax_2','frm1603Q:selTreaty') $null 'official-hta-runtime#disableSelTreaty:L3025-L3029' 'verified-correct' 'Treaty select is disabled and reset to index zero.'
