Add-R '1603q-validate-009' 'validate' 9 'Item 10 telephone is blank.' @('frm1603Q:txtTelNum') 'Please enter a valid Telephone Number  on Item 10.' 'official-hta-runtime#validateForm:L2882-L2886' 'ambiguous' 'Only nonblankness is tested and the message contains a double space.' 'Confirm requiredness and validate a complete number.'
Add-R '1603q-validate-010' 'validate' 10 'Item 9 address is blank.' @('frm1603Q:txtAddress') "Please enter Taxpayer's Registered Address on Item 9." 'official-hta-runtime#validateForm:L2887-L2891'
Add-R '1603q-validate-011' 'validate' 11 'Item 9A ZIP is blank.' @('frm1603Q:txtZipCode') "Please enter Taxpayer's Zip Code on Item 9A." 'official-hta-runtime#validateForm:L2892-L2896'
Add-R '1603q-validate-012' 'validate' 12 'Neither Item 11 category is selected.' @('frm1603Q:CatAgent_P','frm1603Q:CatAgent_G') 'Please select an option for Item 11.' 'official-hta-runtime#validateForm:L2898-L2902'
