Add-R '1603q-save-003' 'save' 3 'RDO value is 000.' @('frm1603Q:rdoCode') 'Please enter a valid RDO Code on Item 7.' 'official-hta-runtime#initialValidateBeforeSave:L3197-L3201'
Add-R '1603q-save-004' 'save' 4 'Item 8 name is blank.' @('frm1603Q:txtTaxpayerName') "Please enter a valid Withholding Agent's Name on Item 8." 'official-hta-runtime#initialValidateBeforeSave:L3202-L3205'
Add-R '1603q-save-005' 'save' 5 'Quarter, TIN, RDO and name pass while other Validate rules fail.' @('other-fields') $null 'official-hta-runtime#initialValidateBeforeSave:L3185-L3205' 'official-bug-compatible' 'Draft Save can persist otherwise invalid data.' 'Clearly mark drafts unvalidated.'
Add-R '1603q-final-001' 'final-copy' 1 'Validated Final Copy is confirmed.' @('txtFinalFlag') "Please ensure that you have INTERNET access and a VALID email address is indicated in your tax return.`n`nAre you sure you want to submit?" 'official-hta-runtime#openAlertEmail:L3805-L3874' 'official-bug-compatible' 'Final Copy is submission-first.' 'Separate local final copy from online submission.'
Add-R '1603q-final-002' 'final-copy' 2 'No network is detected.' @('txtFinalFlag') "The system detected that you have no internet connection.`nPlease contact your internet service provider." 'official-hta-runtime#openAlertEmail:L3805-L3874' 'official-bug-compatible' 'Sets final flag 3 and produces encrypted offline copy.'
Add-R '1603q-submit-001' 'submit' 1 'Transport succeeds.' @('txtFinalFlag') 'Submit Successful. Subject to validation by BIR.' 'official-hta-runtime#sendEmail:L3876-L3978' 'unverified' 'Sets final flag 1 and persists final state.' 'Require authenticated receipt evidence.' 'high' @('Online submission intentionally not performed.')
Add-R '1603q-submit-002' 'submit' 2 'Transport fails or throws.' @('txtFinalFlag') 'Your Tax Return was not submitted online due to any of the following reasons that may interrupt the submission process:' 'official-hta-runtime#sendEmail:L3876-L3978' 'unverified' 'Sets final flag 2 for retry.' 'Retain the actual safe error.' 'high' @('Online submission intentionally not performed.')
$doc=[ordered]@{'$schema'='../../schema/validations.schema.json';schema_version='1.0.0';form_id=$form;revision=$rev;first_error_behavior='Validate and Save stop at the first ordered rejection; blur/change handlers may mutate values first.';rules=$rules};[IO.Directory]::CreateDirectory((Split-Path -Parent $OutputPath))|Out-Null;[IO.File]::WriteAllText($OutputPath,($doc|ConvertTo-Json -Depth 12)+"`n",[Text.UTF8Encoding]::new($false));[ordered]@{rules=$rules.Count}|ConvertTo-Json
